   initial bq_vld = 4'h0;
   initial bq_t0 = 4'h0;
   initial bq_t1 = 4'h0;
   initial bq_wp = 2'd0;
   initial bq_rp = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);
   wire bq_live  = (fsm == S_ARMED) || (fsm == S_RUN);
   wire bq_push  = bq_live && (match0 || match1) && !bq_vld[bq_wp];
   wire bq_pop   = bq_vld[bq_rp];
   wire bq_hd_t0 = bq_t0[bq_rp];
   wire bq_hd_t1 = bq_t1[bq_rp];
   assign bq_full = &bq_vld;
   always @(*)
       case (bq_rp)
           2'd0: bq_head = bq_d0;
           2'd1: bq_head = bq_d1;
           2'd2: bq_head = bq_d2;
           default: bq_head = bq_d3;
       endcase

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
           S_ARMED: if (bq_pop && bq_hd_t0) fsm_nxt = S_RUN;
           S_RUN:   if (bq_pop && bq_hd_t1) fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
           trig_data <= 128'h0;
           bq_d0 <= 128'h0;
           bq_d1 <= 128'h0;
           bq_d2 <= 128'h0;
           bq_d3 <= 128'h0;
           bq_vld <= 4'h0;
           bq_t0 <= 4'h0;
           bq_t1 <= 4'h0;
           bq_wp <= 2'd0;
           bq_rp <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
               bq_vld <= 4'h0;
               bq_wp <= 2'd0;
               bq_rp <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
               if (fsm == S_ARMED && bq_push && match0) started_seen <= 1'b1;
               if (bq_pop) begin
                   bq_vld[bq_rp] <= 1'b0;
                   bq_rp <= bq_rp + 2'd1;
                   if (fsm == S_RUN && bq_hd_t1) trig_data <= bq_head;
               end
               if (bq_push) begin
                   bq_vld[bq_wp] <= 1'b1;
                   bq_t0[bq_wp] <= match0;
                   bq_t1[bq_wp] <= match1;
                   bq_wp <= bq_wp + 2'd1;
                   case (bq_wp)
                       2'd0: bq_d0 <= beat_data;
                       2'd1: bq_d1 <= beat_data;
                       2'd2: bq_d2 <= beat_data;
                       default: bq_d3 <= beat_data;
                   endcase
               end
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage (committed in pairs)
output reg         ret_pend    // one retirement banked, not yet committed to n_acc_out
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
initial ret_pend  = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == (n_acc_out + {3'd0, ret_pend})));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
// retirements are banked in a half-slot and committed to the ledger in pairs;
// an idle cycle flushes a lone banked retirement
if (hit_q || miss_q) begin
    if (ret_pend) begin
        n_acc_out <= n_acc_out + 4'd2;
        ret_pend  <= 1'b0;
    end else
        ret_pend  <= 1'b1;
end else if (ret_pend) begin
    n_acc_out <= n_acc_out + 4'd1;
    ret_pend  <= 1'b0;
end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg       cnt_pend;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        cnt_pend = 1'b0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
            cnt_pend   <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
    if (rd_ptr == 3'd7)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
    2'd2: stat_o <= {8'h0, wrap_cnt, 14'h0, cnt_pend, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
                cnt_pend <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
                cnt      <= cnt + {3'b000, cnt_pend};
                cnt_pend <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                    cnt_pend <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt      <= cnt + {3'b000, cnt_pend};
                    cnt_pend <= 1'b1;
                end
            end else begin
                cnt      <= cnt + {3'b000, cnt_pend};
                cnt_pend <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage
output reg  [15:0] dbg_status   // rotating debug/statistics readout
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
   // ---- debug / statistics bank (observability only) ----
   reg [7:0]  dbg_grant_cnt   = 8'd0;
   reg [7:0]  dbg_fault_cnt   = 8'd0;
   reg [5:0]  dbg_cfg_wr_cnt  = 6'd0;
   reg [5:0]  dbg_cfg_rej_cnt = 6'd0;
   reg [7:0]  dbg_idle_cnt    = 8'd0;
   reg        dbg_wdog_trip   = 1'b0;
   reg [15:0] dbg_addr_d1     = 16'd0;
   reg [15:0] dbg_fault_addr  = 16'd0;
   reg [1:0]  dbg_sel         = 2'd0;
   initial dbg_status = 16'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == n_acc_out));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
if (hit_q || miss_q)
    n_acc_out <= n_acc_out + 4'd1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           dbg_addr_d1 <= acc_addr;
           if (grant && (dbg_grant_cnt != 8'hFF))
               dbg_grant_cnt <= dbg_grant_cnt + 8'd1;
           if (fault && (dbg_fault_cnt != 8'hFF))
               dbg_fault_cnt <= dbg_fault_cnt + 8'd1;
           if (miss_q)
               dbg_fault_addr <= dbg_addr_d1;
           if (cfg_we) begin
               if (pre_lock && (cfg_idx < 5'd24))
                   dbg_cfg_wr_cnt <= dbg_cfg_wr_cnt + 6'd1;
               else
                   dbg_cfg_rej_cnt <= dbg_cfg_rej_cnt + 6'd1;
           end
           if (acc_valid) begin
               dbg_idle_cnt  <= 8'd0;
               dbg_wdog_trip <= 1'b0;
           end else if (dbg_idle_cnt == 8'hFF)
               dbg_wdog_trip <= 1'b1;
           else
               dbg_idle_cnt <= dbg_idle_cnt + 8'd1;
           dbg_sel <= dbg_sel + 2'd1;
           case (dbg_sel)
               2'd0:    dbg_status <= {dbg_grant_cnt, dbg_fault_cnt};
               2'd1:    dbg_status <= {dbg_cfg_wr_cnt, dbg_cfg_rej_cnt, pre_lock, dbg_wdog_trip, 2'b00};
               2'd2:    dbg_status <= dbg_fault_addr;
               default: dbg_status <= {dbg_idle_cnt, 4'd0, n_acc_in - n_acc_out};
           endcase
       end
   end

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module xbar_route_rom (
