               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

