    ra_blk_o <= ra_blk_o + 16'd1;
if (ra_lvl > ra_hwm_o)
    ra_hwm_o <= ra_lvl;
if (rb_lvl > rb_hwm_o)
    rb_hwm_o <= rb_lvl;
if (rb_blk && !start && !stop)
    rb_blk_o <= rb_blk_o + 16'd1;
if (win && !start && !stop) begin
    ra_occ_o <= ra_occ_o + {13'h0, ra_lvl};
    rb_occ_o <= rb_occ_o + {13'h0, rb_lvl};
